class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None


class Solution:

    # Returns subtree height
    # measured in nodes.
    def find_height(self, node):
        # An empty subtree
        # has height zero.
        if node is None:
            return 0

        left_height = self.find_height(
            node.left
        )

        right_height = self.find_height(
            node.right
        )

        return 1 + max(
            left_height,
            right_height
        )

    # Checks every node as the
    # highest point of the diameter.
    def find_diameter(self, node):
        # An empty subtree
        # has diameter zero.
        if node is None:
            return 0

        # Heights from both children form
        # the path through this node.
        left_height = self.find_height(
            node.left
        )

        right_height = self.find_height(
            node.right
        )

        current_diameter = (
            left_height + right_height
        )

        # The longest path may lie
        # completely inside either subtree.
        left_diameter = self.find_diameter(
            node.left
        )

        right_diameter = self.find_diameter(
            node.right
        )

        return max(
            current_diameter,
            left_diameter,
            right_diameter
        )

    # Returns the diameter
    # measured in edges.
    def diameter_of_binary_tree(self, root):
        return self.find_diameter(root)


